def predict(board, action):
    if action[0] == 'MOUSE' and action[1] == 31 and action[2] == 19:
        mouse_char = board[31][19]
        new_board = [list(row) for row in board]
        for i in range(64):
            if new_board[i][19] == mouse_char:
                new_board[i][19] = ''
        new_board[31][19] = 'MOUSE'
        return [''.join(row) for row in new_board]
    else:
        return board
